            JSONObject job=new JSONObject().put("format","pocketworld.native-git-import-job.v1").put("version",1).put("operationId",id).put("planDigest",plan.getString("planDigest")).put("url",selected.review.target.url).put("host",selected.review.target.host).put("port",selected.review.target.port).put("branch",plan.getString("branch")).put("gitArgv",tools.getJSONArray("gitArgv")).put("gitExecutableSha256",tools.getString("gitExecutableSha256")).put("path",tools.getString("path")).put("networkScope","one_reviewed_https_origin_and_pinned_ip").put("repositoryScriptsAllowed",false).put("timeoutSeconds",600);
