            JSONArray files=manifest.getJSONArray("files");if(files.length()==0||files.length()>2000||manifest.getInt("fileCount")!=files.length())throw new SecurityException("原Git源码清单缺失或超限");JSONArray source=new JSONArray();Set<String> seen=new HashSet<>();long total=0;for(int i=0;i<files.length();i++){observation.checkpoint();JSONObject row=files.getJSONObject(i);String path=ProjectGit.path(row.getString("path"));if(!seen.add(path)||row.getLong("bytes")<0||row.getLong("bytes")>2*1024*1024||!row.getString("sha256").matches("[a-f0-9]{64}"))throw new SecurityException("原Git文件版本清单无效");byte[] bytes=checked(within(repository,path),2*1024*1024,observation);if(bytes.length!=row.getLong("bytes")||!ProjectSources.sha256(bytes).equals(row.getString("sha256")))throw new SecurityException("Git已读源码在核对中变化");total+=bytes.length;if(total>16*1024*1024)throw new SecurityException("Git源码超过16MiB");if(ProjectSources.sourcePath(path))source.put(new JSONObject().put("path",path).put("bytes",bytes.length).put("sha256",row.getString("sha256")));}
